  m1 = U8TO64(block + 8);
  m2 = U8TO64(block + 16);
  m3 = U8TO64(block + 24);
  m4 = U8TO64(block + 32);
  m5 = U8TO64(block + 40);
  m6 = U8TO64(block + 48);
  m7 = U8TO64(block + 56);
  m8 = U8TO64(block + 64);
  m9 = U8TO64(block + 72);
  m10 = U8TO64(block + 80);
  m11 = U8TO64(block + 88);
  m12 = U8TO64(block + 96);
  m13 = U8TO64(block + 104);
  m14 = U8TO64(block + 112);
  m15 = U8TO64(block + 120);
  v0 = S->h[0];
  v1 = S->h[1];
  v2 = S->h[2];
  v3 = S->h[3];
  v4 = S->h[4];
  v5 = S->h[5];
  v6 = S->h[6];
  v7 = S->h[7];
