  v9 = S->s[1] ^ 0x13198A2E03707344ULL;
  v10 = S->s[2] ^ 0xA4093822299F31D0ULL;
  v11 = S->s[3] ^ 0x082EFA98EC4E6C89ULL;
  v12 = 0x452821E638D01377ULL;
  v13 = 0xBE5466CF34E90C6CULL;
  v14 = 0xC0AC29B7C97C50DDULL;
  v15 = 0x3F84D5B5B5470917ULL;

