                  v3 += v4; \
                  v14 ^= v3; \
                  v14 = BLAKE512_ROT( v14,32); \
                  v9 += v14; \
                  v4 ^= v9; \
                  v4 = BLAKE512_ROT( v4,25); \
                v2 += m13 ^ c13; \
                v2 += v7; \
                v13 ^= v2; \
                v13 = BLAKE512_ROT( v13,16); \
                v8 += v13; \
                v7 ^= v8; \
                v7 = BLAKE512_ROT( v7,11); \
                  v3 += m15 ^ c15; \
                  v3 += v4; \
                  v14 ^= v3; \
                  v14 = BLAKE512_ROT( v14,16); \
                  v9 += v14; \
                  v4 ^= v9; \
                  v4 = BLAKE512_ROT( v4,11); \
              v1 += m11 ^ c11; \
              v1 += v6; \
              v12 ^= v1; \
              v12 = BLAKE512_ROT( v12,16); \
              v11 += v12; \
              v6 ^= v11; \
              v6 = BLAKE512_ROT( v6,11); \
            v0 += m9 ^ c9; \
            v0 += v5; \
